// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/me/grievances", wrapper.ListMyGrievances)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/me/grievances", wrapper.CreateGrievance)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/account-lookups", wrapper.LookupAccount)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/access-requests", wrapper.RequestStaffAccess)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/access-requests/{requestId}/approve", wrapper.ApproveStaffAccess)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/access-requests/{requestId}/reject", wrapper.RejectStaffAccess)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/break-glass", wrapper.BreakGlassAccess)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/access-reviews/{month}", wrapper.MonthlyAccessReview)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/grievances", wrapper.ListGrievanceQueue)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/grievances/{grievanceId}/acknowledge", wrapper.AcknowledgeGrievance)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/grievances/{grievanceId}/resolve", wrapper.ResolveGrievance)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/grievance-alerts", wrapper.ListGrievanceAlerts)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/me/feedback", wrapper.ListMyFeedback)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/me/feedback", wrapper.CreateFeedback)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/feedback", wrapper.ListFeedbackForTriage)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/feedback/{feedbackId}/status", wrapper.SetFeedbackStatus)
	})

	return r
}

